function getRegions() {
  return REGIONS;
}

function getDistrictsByRegion(regionId) {
  return DISTRICTS.filter((d) => d.regionId === Number(regionId));
}

function getRegionById(regionId) {
  return REGIONS.find((r) => r.id === Number(regionId));
}

function getDistrictById(districtId) {
  return DISTRICTS.find((d) => d.id === Number(districtId));
}

module.exports = { getRegions, getDistrictsByRegion, getRegionById, getDistrictById };
